-- CAP-249 Story #11: Reschedule history table for audit trail of appointment rescheduling
-- Per business rule: max 2 reschedules without manager approval; immutable retention policy applies.
CREATE TABLE reschedule_history (
    -- ID is always generated by the application layer (UUIDv7) before insert
    reschedule_id         UUID         NOT NULL PRIMARY KEY,
    appointment_id        UUID         NOT NULL,
    previous_start_at     TIMESTAMPTZ  NOT NULL,
    previous_end_at       TIMESTAMPTZ  NOT NULL,
    new_start_at          TIMESTAMPTZ  NOT NULL,
    new_end_at            TIMESTAMPTZ  NOT NULL,
    reschedule_reason     VARCHAR(50)  NOT NULL,
    reschedule_reason_notes VARCHAR(1000),
    rescheduled_by        VARCHAR(255) NOT NULL,
    rescheduled_at        TIMESTAMPTZ  NOT NULL,
    conflict_overridden   BOOLEAN      NOT NULL DEFAULT FALSE,
    assignment_status     VARCHAR(50),
    notify_customer       BOOLEAN      NOT NULL DEFAULT TRUE,
    notification_status   VARCHAR(50),
    created_at            TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE INDEX idx_reschedule_history_appointment_id ON reschedule_history (appointment_id);
